import * as React from 'react';
import { useState, useEffect } from 'react';
import { supabase } from './services/supabase';
import { Auth } from './components/Auth';
import { MainTerminal } from './components/MainTerminal';
import { ToastProvider } from './components/Toast';
import KeepAlive from './components/KeepAlive';
import { Session } from '@supabase/supabase-js';

// Componente Wrapper para proporcionar el contexto global
const AppWrapper = () => (
  <ToastProvider>
    <KeepAlive />
    <App />
  </ToastProvider>
);

const App: React.FC = () => {
  const [session, setSession] = useState<Session | null>(null);
  const [isSessionLoading, setIsSessionLoading] = useState(true);
  const [authCallbackMessage, setAuthCallbackMessage] = useState<string | null>(null);
  const [authCallbackError, setAuthCallbackError] = useState<string | null>(null);

  // Gestión de la Sesión de Supabase
  useEffect(() => {
    const pathname = window.location.pathname;
    const hashParams = new URLSearchParams(window.location.hash.replace(/^#/, ''));
    const searchParams = new URLSearchParams(window.location.search);
    const isAuthCallback = pathname === '/auth/callback';

    if (isAuthCallback) {
      const errorDescription = hashParams.get('error_description') || searchParams.get('error_description');
      const accessToken = hashParams.get('access_token');

      if (errorDescription) {
        setAuthCallbackError(decodeURIComponent(errorDescription.replace(/\+/g, ' ')));
      } else if (accessToken) {
        setAuthCallbackMessage('Confirmación recibida. Estamos abriendo tu sesión...');
      } else {
        setAuthCallbackMessage('Tu correo fue confirmado. Ya puedes iniciar sesión en Synapse.');
      }
    }

    if (supabase) {
      // 1. Obtener sesión actual inicial
      supabase.auth.getSession().then(({ data: { session } }) => {
        setSession(session);
        setIsSessionLoading(false);

        if (session && isAuthCallback) {
          window.history.replaceState({}, document.title, '/');
        }
      });

      // 2. Escuchar cambios en el estado de autenticación
      const { data: { subscription } } = supabase.auth.onAuthStateChange((event, session) => {
        setSession(session);
        setIsSessionLoading(false);

        if (session && isAuthCallback) {
          if (event === 'SIGNED_IN' || event === 'INITIAL_SESSION') {
            setAuthCallbackMessage('Correo confirmado correctamente. Bienvenido a Synapse.');
          }
          window.history.replaceState({}, document.title, '/');
        }
      });

      return () => subscription.unsubscribe();
    } else {
      setIsSessionLoading(false);
    }
  }, []);

  // Pantalla de Carga Inicial
  if (isSessionLoading) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen bg-[#0a0c10] text-slate-200">
        <div className="relative w-16 h-16 mb-4">
          <div className="absolute inset-0 border-[4px] border-sky-500/10 rounded-full"></div>
          <div className="absolute inset-0 border-[4px] border-sky-500 border-t-transparent rounded-full animate-spin"></div>
        </div>
        <p className="text-[10px] mono text-slate-500 font-bold uppercase tracking-[0.3em] animate-pulse">Iniciando Synapse QA...</p>
      </div>
    );
  }

  // Si no hay sesión, mostrar el Login (Auth)
  if (!session) {
    return <Auth onLoginSuccess={() => { }} initialMessage={authCallbackMessage} initialError={authCallbackError} />; // El onAuthStateChange manejará la redirección
  }

  // Si hay sesión, mostrar la Terminal Principal
  return <MainTerminal session={session} />;
};

export default AppWrapper;

require('dotenv').config();
const express = require('express');
const path = require('path');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { GoogleGenAI } = require('@google/genai');

const app = express();
const PORT = process.env.PORT || 4000;

app.use(cors());
app.use(express.json());

// Rate limiting: máximo 15 peticiones por minuto por IP al endpoint de IA
const aiLimiter = rateLimit({
  windowMs: 60 * 1000, // 1 minuto
  max: 15,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Demasiadas peticiones. Intenta de nuevo en un minuto.' }
});

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date() });
});

// --- PROXY IA ---

// Instrucciones para Gemini / Groq
// IMPORTANTE: Groq requiere que el prompt contenga la palabra "json"
// cuando se usa response_format: { type: "json_object" }.
const SYSTEM_INSTRUCTION = `Eres el sistema central de auditoría SYNAPSE // QA.
Tu misión es procesar reportes técnicos con precisión quirúrgica.
1. Analiza con rigor: fallos de UI, errores de lógica, problemas de codificación (UTF-8) y regresiones funcionales.
2. Clasifica obligatoriamente en: 'UI/UX', 'Backend', 'Datos', 'Seguridad', 'Rendimiento'.
3. El resumen ejecutivo debe ser directo, técnico y profesional (evita saludos).
4. Para cada hallazgo:
   - Título: Conciso y técnico.
   - Descripción: Detalle del comportamiento observado vs esperado.
   - Severidad: Alta/Media/Baja.
   - Solución: Instrucciones técnicas de remediación.
RESPONDE SIEMPRE EN ESPAÑOL. Usa terminología de ingeniería de software moderna.
DEVUELVE ÚNICAMENTE un objeto JSON válido con la estructura:
{ "summary": string, "issues": Array<{ id, title, desc, category, severity, fix }> }`;

const TASK_SYSTEM_INSTRUCTION = `Eres el gestor de incidentes SYNAPSE // TASKS.
Tu misión es transformar descripciones de lenguaje natural en una lista estructurada de tareas técnicas pendientes (To-Do List).
1. Analiza el texto entrada buscando intenciones, pendientes y requerimientos.
2. Identifica verbos de acción y contextos técnicos.
3. Añade al menos un "summary" o "resumen" general de las tareas que explique su propósito.
4. Clasifica cada tarea obligatoriamente en: 'UI/UX', 'Backend', 'Datos', 'Seguridad', 'Rendimiento'.
5. Asigna prioridad (Severity) basada en la urgencia o importancia del contexto (ej: seguridad/crítico -> Alta).
6. Para cada tarea incluye campos claramente nombrados: 'title' (resumen breve), 'desc' (detalle del trabajo), una breve 'fix' o 'plan_tecnico' con la sugerencia de resolución técnica y, si aplica, 'category' y 'severity'.
7. Estructura de salida JSON e incluye el campo "issues" con el arreglo de tareas y "summary" con el texto principal.
RESPONDE SIEMPRE EN ESPAÑOL.
DEVUELVE ÚNICAMENTE un objeto JSON válido con la estructura:
{ "summary": string, "issues": Array<{ id, title, desc, category, severity, fix }> }`;

// Endpoint de análisis de issues
app.post('/api/analyze', aiLimiter, async (req, res) => {
  const { input, provider, apiKey, isTask } = req.body;

  // Validación: el input no puede estar vacío ni exceder 10,000 caracteres
  if (!input || typeof input !== 'string' || !input.trim()) {
    return res.status(400).json({ error: 'El campo "input" es requerido.' });
  }
  if (input.length > 10000) {
    return res.status(400).json({ error: `El texto de entrada supera el límite de 10,000 caracteres (actual: ${input.length}).` });
  }
  // Usar la key del body (del usuario) o la del servidor (.env)
  const geminiKey = apiKey || process.env.GEMINI_API_KEY || process.env.VITE_GEMINI_API_KEY;
  const groqKey = apiKey || process.env.GROQ_API_KEY || process.env.VITE_GROQ_API_KEY;

  try {
    if (provider === 'gemini') {
      if (!geminiKey) return res.status(400).json({ error: 'Falta Gemini API Key' });

      const genAI = new GoogleGenAI({ apiKey: geminiKey });
      const model = genAI.getGenerativeModel({
        model: "gemini-2.0-flash",
        systemInstruction: isTask ? TASK_SYSTEM_INSTRUCTION : SYSTEM_INSTRUCTION
      });

      const result = await model.generateContent(input);
      const response = await result.response;
      let text = response.text();

      // Limpiar markdown si Gemini lo envía
      text = text.replace(/```json/g, '').replace(/```/g, '').trim();

      // parsear y normalizar para asegurar campos mínimos
      const parsed = JSON.parse(text);
      if (parsed) {
        parsed.summary = parsed.summary || parsed.resumen || '[sin resumen]';
        if (Array.isArray(parsed.issues)) {
          parsed.issues = parsed.issues.map((i, idx) => {
            const id = i.id || i.ID || i.external_id || idx + 1;
            const title = i.title || i.titulo || i.descripcion || i.description || '[sin título]';
            const desc = i.desc || i.descripcion || i.detalles || i.detail || '[sin descripción]';
            const fix = i.fix || i.resolucion || i.plan_tecnico || i.plan_accion || i.plan || '';
            const rawSeverity = i.severity || i.prioridad || i.gravedad || i.level || 'Baja';
            return {
              ...i,
              id,
              title,
              desc,
              fix,
              severity: rawSeverity
            };
          });
        }
      }

      res.json(parsed);

    } else if (provider === 'groq') {
      if (!groqKey) return res.status(400).json({ error: 'Falta Groq API Key' });

      // para mantener consistencia, reutilizamos las mismas instrucciones que
      // usamos con Gemini; de este modo ambos proveedores reciben el mismo
      // contexto detallado y es más fácil ajustar el prompt en un único lugar.
      const systemPrompt = isTask ? TASK_SYSTEM_INSTRUCTION : SYSTEM_INSTRUCTION;

      const response = await fetch("https://api.groq.com/openai/v1/chat/completions", {
        method: "POST",
        headers: {
          "Authorization": `Bearer ${groqKey}`,
          "Content-Type": "application/json"
        },
        body: JSON.stringify({
          model: "llama-3.3-70b-versatile",
          messages: [
            { role: "system", content: systemPrompt },
            { role: "user", content: input }
          ],
          // el tipo 'json_object' ya nos obliga a recibir JSON válido, pero
          // también podríamos añadir un esquema si se necesitara validar
          // campos concretos. Por ahora las instrucciones del systemPrompt
          // piden explícitamente title/desc/severity/fix/category.
          response_format: { type: "json_object" },
          temperature: 0.1
        })
      });

      const data = await response.json();
      if (data.error) throw new Error(data.error.message);

      res.json(JSON.parse(data.choices[0].message.content));
    } else {
      res.status(400).json({ error: 'Proveedor no válido' });
    }
  } catch (error) {
    console.error('Error en Proxy IA:', error);
    res.status(500).json({ error: error.message });
  }
});

// --- FIN PROXY IA ---

// --- ENDPOINTS DE EXPORTACIÓN (GITHUB & TRELLO) ---

// Exportar a GitHub Issues
app.post('/api/export/github', async (req, res) => {
  const { owner, repo, token, title, body } = req.body;

  if (!owner || !repo || !token || !title) {
    return res.status(400).json({ error: 'Faltan parámetros requeridos para GitHub' });
  }

  try {
    const response = await fetch(`https://api.github.com/repos/${owner}/${repo}/issues`, {
      method: 'POST',
      headers: {
        'Authorization': `token ${token}`,
        'Accept': 'application/vnd.github.v3+json',
        'Content-Type': 'application/json',
        'User-Agent': 'Synapse-QA-App'
      },
      body: JSON.stringify({ title, body })
    });

    const data = await response.json();
    if (!response.ok) throw new Error(data.message || 'Error en la API de GitHub');

    res.json({ success: true, url: data.html_url });
  } catch (error) {
    console.error('GitHub Export Error:', error);
    res.status(500).json({ error: error.message });
  }
});

// Verificar token de GitHub
app.post('/api/verify/github', async (req, res) => {
  const { token } = req.body;
  if (!token) return res.status(400).json({ error: 'Falta el token' });

  try {
    const response = await fetch('https://api.github.com/user', {
      headers: {
        'Authorization': `token ${token}`,
        'Accept': 'application/vnd.github.v3+json',
        'User-Agent': 'Synapse-QA-App'
      }
    });
    const data = await response.json();
    if (!response.ok) throw new Error(data.message || 'Token inválido');
    res.json({ success: true, user: data.login });
  } catch (error) {
    res.status(401).json({ error: error.message });
  }
});

// Exportar a Trello Cards
app.post('/api/export/trello', async (req, res) => {
  const { key, token, idList, name, desc } = req.body;

  if (!key || !token || !idList || !name) {
    return res.status(400).json({ error: 'Faltan parámetros requeridos para Trello' });
  }

  try {
    const url = `https://api.trello.com/1/cards?idList=${idList}&key=${key}&token=${token}&name=${encodeURIComponent(name)}&desc=${encodeURIComponent(desc)}`;

    const response = await fetch(url, { method: 'POST' });
    const data = await response.json();

    if (!response.ok) throw new Error(data || 'Error en la API de Trello');

    res.json({ success: true, url: data.shortUrl });
  } catch (error) {
    console.error('Trello Export Error:', error);
    res.status(500).json({ error: error.message });
  }
});

// Verificar credenciales de Trello
app.post('/api/verify/trello', async (req, res) => {
  const { key, token } = req.body;
  if (!key || !token) return res.status(400).json({ error: 'Faltan credenciales' });

  try {
    const response = await fetch(`https://api.trello.com/1/members/me?key=${key}&token=${token}`);
    const data = await response.json();
    if (!response.ok) throw new Error(typeof data === 'string' ? data : 'Credenciales inválidas');
    res.json({ success: true, user: data.fullName });
  } catch (error) {
    res.status(401).json({ error: error.message });
  }
});

// Serve static files from frontend build
app.use(express.static(path.join(__dirname, '../dist')));

// Explicitly serve crawler files before SPA fallback.
app.get('/robots.txt', (_req, res) => {
  res.type('text/plain');
  res.sendFile(path.join(__dirname, '../dist', 'robots.txt'));
});

app.get('/sitemap.xml', (_req, res) => {
  res.type('application/xml');
  res.sendFile(path.join(__dirname, '../dist', 'sitemap.xml'));
});

// Fallback to index.html for SPA
app.get('*', (req, res) => {
  res.sendFile(path.join(__dirname, '../dist', 'index.html'));
});

app.listen(PORT, () => {
  console.log(`Backend server running on http://localhost:${PORT}`);
});

import React, { useEffect, useState } from 'react';
import { supabase } from '../services/supabase';
import { AuthHeader } from './AuthHeader';
import { AuthFooter, AuthToggle } from './AuthFooter';

interface AuthProps {
    onLoginSuccess: () => void;
    initialMessage?: string | null;
    initialError?: string | null;
}

export const Auth: React.FC<AuthProps> = ({ onLoginSuccess, initialMessage = null, initialError = null }) => {
    const [loading, setLoading] = useState(false);
    const [loginSuccess, setLoginSuccess] = useState(false);
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [isSignUp, setIsSignUp] = useState(false);
    const [error, setError] = useState<string | null>(initialError);
    const [message, setMessage] = useState<string | null>(initialMessage);

    useEffect(() => {
        setMessage(initialMessage);
    }, [initialMessage]);

    useEffect(() => {
        setError(initialError);
    }, [initialError]);

    const handleAuth = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!supabase) return;

        setLoading(true);
        setError(null);
        setMessage(null);

        try {
            if (isSignUp) {
                const emailRedirectTo = `${window.location.origin}/auth/callback`;
                const { error } = await supabase.auth.signUp({
                    email,
                    password,
                    options: {
                        emailRedirectTo,
                    },
                });
                if (error) throw error;
                setMessage('¡Registro exitoso! Revisa tu correo y confirma tu cuenta para volver a Synapse.');
            } else {
                const { error } = await supabase.auth.signInWithPassword({ email, password });
                if (error) throw error;
                setLoginSuccess(true);
                setTimeout(() => { onLoginSuccess(); }, 1500);
            }
        } catch (err: any) {
            setError(err.message || 'Error de autenticación');
        } finally {
            if (!loginSuccess) setLoading(false);
        }
    };

    if (!supabase) return (
        <div className="flex items-center justify-center min-h-screen bg-[#060810]">
            <div className="text-red-500 p-8 text-center font-bold uppercase tracking-widest text-sm">
                Error: Nuclear Core Offline
            </div>
        </div>
    );

    return (
        <div className="flex flex-col items-center justify-center min-h-screen min-h-dvh bg-[#060810] text-slate-200 px-4 py-8 sm:py-12 relative overflow-hidden">

            {/* Grid overlay texture */}
            <div
                className="absolute inset-0 opacity-[0.03] pointer-events-none"
                style={{
                    backgroundImage: `linear-gradient(#38bdf8 1px, transparent 1px), linear-gradient(90deg, #38bdf8 1px, transparent 1px)`,
                    backgroundSize: '60px 60px',
                }}
            />

            {/* Radial gradient vignette */}
            <div className="absolute inset-0 bg-[radial-gradient(ellipse_80%_60%_at_50%_-10%,rgba(14,165,233,0.12),transparent)] pointer-events-none" />
            <div className="absolute inset-0 bg-[radial-gradient(ellipse_60%_50%_at_80%_80%,rgba(99,102,241,0.08),transparent)] pointer-events-none" />

            {/* Corner accents — hidden on tiny screens */}
            <div className="hidden sm:block absolute top-6 left-6 md:top-8 md:left-8 w-12 h-12 md:w-16 md:h-16 border-t-2 border-l-2 border-sky-500/30 rounded-tl-lg pointer-events-none" />
            <div className="hidden sm:block absolute top-6 right-6 md:top-8 md:right-8 w-12 h-12 md:w-16 md:h-16 border-t-2 border-r-2 border-sky-500/30 rounded-tr-lg pointer-events-none" />
            <div className="hidden sm:block absolute bottom-6 left-6 md:bottom-8 md:left-8 w-12 h-12 md:w-16 md:h-16 border-b-2 border-l-2 border-sky-500/30 rounded-bl-lg pointer-events-none" />
            <div className="hidden sm:block absolute bottom-6 right-6 md:bottom-8 md:right-8 w-12 h-12 md:w-16 md:h-16 border-b-2 border-r-2 border-sky-500/30 rounded-br-lg pointer-events-none" />

            {/* Floating orbs */}
            <div className="absolute top-[15%] left-[10%] w-48 h-48 sm:w-72 sm:h-72 bg-sky-500 rounded-full filter blur-[120px] sm:blur-[140px] opacity-[0.07] animate-blob pointer-events-none" />
            <div className="absolute top-[55%] right-[8%] w-56 h-56 sm:w-80 sm:h-80 bg-indigo-500 rounded-full filter blur-[120px] sm:blur-[140px] opacity-[0.06] animate-blob animation-delay-2000 pointer-events-none" />
            <div className="absolute bottom-[10%] left-[35%] w-44 h-44 sm:w-64 sm:h-64 bg-cyan-400 rounded-full filter blur-[120px] sm:blur-[140px] opacity-[0.05] animate-blob animation-delay-4000 pointer-events-none" />

            {/* Scanline shimmer */}
            <div className="absolute inset-0 overflow-hidden pointer-events-none">
                <div className="absolute inset-0 bg-gradient-to-b from-transparent via-sky-500/[0.015] to-transparent animate-scan" />
            </div>

            {/* ── Success Overlay ── */}
            {loginSuccess && (
                <div className="fixed inset-0 z-[200] flex items-center justify-center pointer-events-none bg-[#060810]/70 backdrop-blur-md animate-in fade-in duration-500 px-4">
                    <div className="absolute inset-0 bg-[radial-gradient(ellipse_50%_50%_at_50%_50%,rgba(16,185,129,0.08),transparent)]" />

                    <div className="text-center relative w-full max-w-xs sm:max-w-sm">
                        {/* Concentric rings */}
                        <div className="absolute -inset-16 sm:-inset-24 flex items-center justify-center">
                            <div className="absolute w-40 h-40 sm:w-48 sm:h-48 rounded-full border border-emerald-500/10 animate-ping" style={{ animationDuration: '2s' }} />
                            <div className="absolute w-56 h-56 sm:w-64 sm:h-64 rounded-full border border-emerald-500/5 animate-ping" style={{ animationDuration: '2.5s', animationDelay: '0.3s' }} />
                        </div>

                        {/* Lock icon */}
                        <div className="relative w-16 h-16 sm:w-20 sm:h-20 mx-auto mb-6 sm:mb-10">
                            <div className="absolute inset-0 bg-emerald-500/10 rounded-2xl blur-xl animate-pulse" />
                            <div className="relative w-full h-full bg-emerald-500/10 border border-emerald-500/20 rounded-2xl flex items-center justify-center backdrop-blur-sm">
                                <svg className="w-8 h-8 sm:w-10 sm:h-10 text-emerald-400" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                                    <path d="M7 10V7C7 4.23858 9.23858 2 12 2C14.7614 2 17 4.23858 17 7V10" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
                                    <rect x="5" y="10" width="14" height="12" rx="3" fill="currentColor" stroke="currentColor" strokeWidth="1" className="opacity-30" />
                                    <rect x="5" y="10" width="14" height="12" rx="3" stroke="currentColor" strokeWidth="1.5" className="opacity-80" />
                                    <circle cx="12" cy="15" r="1.5" fill="#064e3b" />
                                    <path d="M12 16.5V18" stroke="#064e3b" strokeWidth="1.5" strokeLinecap="round" />
                                </svg>
                            </div>
                        </div>

                        <div className="space-y-2 sm:space-y-3 animate-in slide-in-from-bottom-4 duration-700 delay-300 fill-mode-both">
                            <div className="font-mono text-[9px] text-emerald-500/50 uppercase tracking-[0.4em] sm:tracking-[0.5em] mb-3 sm:mb-4">// 200 OK</div>
                            <h2 className="text-3xl sm:text-5xl font-black text-white uppercase tracking-tighter">
                                Acceso <span className="text-emerald-400">Concedido</span>
                            </h2>
                            <p className="text-slate-500 font-mono text-[10px] uppercase tracking-[0.3em] sm:tracking-[0.4em] mt-2">Sincronización de Núcleo Completa</p>
                        </div>
                    </div>
                </div>
            )}

            {/* ── Main card ── */}
            <div
                className={`
                    w-full max-w-[420px] relative transition-all duration-700
                    ${loginSuccess ? 'scale-90 opacity-0 blur-lg' : 'scale-100 opacity-100'}
                `}
            >
                {/* Glow border */}
                <div className="absolute -inset-px rounded-2xl bg-gradient-to-b from-sky-500/20 via-transparent to-indigo-500/10 pointer-events-none" />
                <div className="absolute -inset-[2px] rounded-2xl bg-gradient-to-b from-slate-700/30 to-transparent opacity-50 pointer-events-none" />

                <div className="relative bg-[#0c0f1a]/90 border border-slate-800/60 rounded-2xl shadow-2xl shadow-black/60 backdrop-blur-2xl overflow-hidden">

                    {/* Top accent line */}
                    <div className="absolute top-0 left-0 right-0 h-px bg-gradient-to-r from-transparent via-sky-400/60 to-transparent" />
                    <div className="absolute top-0 left-1/4 right-1/4 h-[2px] bg-sky-400/20 blur-sm" />

                    {/* Inner corner dots */}
                    <div className="absolute top-3 left-3 w-1 h-1 rounded-full bg-sky-500/40" />
                    <div className="absolute top-3 right-3 w-1 h-1 rounded-full bg-sky-500/40" />

                    {/* Padding adapts: compact on mobile, generous on larger */}
                    <div className="p-5 sm:p-8">

                        {/* Status bar */}
                        <div className="flex items-center justify-between mb-6 sm:mb-8 px-1">
                            <div className="flex items-center gap-1.5">
                                <div className="w-1.5 h-1.5 rounded-full bg-emerald-500 shadow-[0_0_6px_rgba(16,185,129,0.8)] animate-pulse" />
                                <span className="font-mono text-[9px] text-slate-500 uppercase tracking-[0.25em] sm:tracking-[0.3em]">Sistema Activo</span>
                            </div>
                            <span className="font-mono text-[9px] text-slate-600 uppercase tracking-widest">v2.4.1</span>
                        </div>

                        <AuthHeader />

