    const canManageCollaborators = !!currentAuditMeta?.isOwner;
    const collaboratorEmails = Array.from(new Set([currentUserEmail, ...currentCollaborators.map(c => c.invited_email)]));

    const [loadingMessage, setLoadingMessage] = useState('Analizando trazas...');
    const messages = [
        "Iniciando escaneo neural...",
        "Procesando entrada de datos...",
        "Analizando trazas de error...",
        "Extrayendo lo más importante...",
        "Sincronizando con el núcleo Synapse...",
        isDbConnected ? "Almacenando en base de datos central..." : "Preparando respuesta local..."
    ];

    useEffect(() => {
        if (isDbConnected && session) {
            fetchRecentAudits();
            fetchUserConfig();
        } else {
            // sin sesión o sin DB, también intentamos cargar desde localStorage
            const owner = localStorage.getItem('gh_owner');
            if (owner) {
                setGithubOwner(owner);
                setGithubRepo(localStorage.getItem('gh_repo') || '');
                setGithubToken(localStorage.getItem('gh_token') || '');
                setTrelloKey(localStorage.getItem('trello_key') || '');
                setTrelloToken(localStorage.getItem('trello_token') || '');
                setTrelloListId(localStorage.getItem('trello_list_id') || '');
                setCustomGeminiKey(localStorage.getItem('gemini_key') || '');
                setCustomGroqKey(localStorage.getItem('groq_key') || '');
            }
        }
    }, [isDbConnected, session]);

    useEffect(() => {
        let interval: number;
        if (isAnalyzing) {
            let idx = 0;
            interval = window.setInterval(() => {
                idx = (idx + 1) % messages.length;
                setLoadingMessage(messages[idx]);
            }, 2000);
        }
        return () => clearInterval(interval);
    }, [isAnalyzing]);

    useEffect(() => {
        if (!currentAuditId) return;
        const refreshedAudit = recentAudits.find(a => String(a.id) === String(currentAuditId));
        if (refreshedAudit) {
            setCurrentAuditMeta(refreshedAudit);
        }
    }, [recentAudits, currentAuditId]);

    const mapAuditWithStatus = (audit: any, overrides?: Partial<AuditRecord>): AuditRecord => {
        const totalIssues = audit.issues?.length || 0;
        const completedIssues = audit.issues?.filter((i: any) => i.is_done).length || 0;

        return {
            ...audit,
            isCompleted: totalIssues > 0 && totalIssues === completedIssues,
            totalIssues,
            completedIssues,
            isOwner: true,
            accessLevel: 'owner',
            ownerEmail: currentUserEmail,
            ...overrides,
        };
    };

    const fetchCurrentAuditCollaborators = async (auditId: string | number) => {
        if (!supabase) return;

        const { data, error } = await supabase
            .from('audit_collaborators')
            .select('invited_email, access_level, created_at')
            .eq('audit_id', auditId)
            .order('created_at', { ascending: true });

        if (error) {
            if (!error.message.toLowerCase().includes('audit_collaborators')) {
                console.error('Error al cargar colaboradores:', error);
            }
            setCurrentCollaborators([]);
            return;
        }

        setCurrentCollaborators((data || []) as AuditCollaborator[]);
    };

    const ensureCurrentUserProfile = async () => {
        if (!supabase || !session || !currentUserEmail) return;

        const { error } = await supabase
            .from('user_profiles')
            .upsert([{
                user_id: session.user.id,
                email: currentUserEmail,
                display_name: session.user.user_metadata?.full_name || session.user.user_metadata?.name || currentUserEmail,
            }], { onConflict: 'user_id' });

        if (error && !error.message.toLowerCase().includes('user_profiles')) {
            console.error('No se pudo sincronizar el perfil público del usuario:', error);
        }
    };

    useEffect(() => {
        if (!supabase || !currentAuditId) return;

        const channel = supabase
            .channel(`audit-live-${currentAuditId}`)
            .on('postgres_changes', {
                event: '*',
                schema: 'public',
                table: 'issues',
                filter: `audit_id=eq.${currentAuditId}`,
            }, async () => {
                const { data } = await supabase
                    .from('issues')
                    .select('*')
                    .eq('audit_id', currentAuditId)
                    .order('external_id', { ascending: true });

                if (data) {
                    setIssues(data.map((si: any) => ({
                        dbId: si.id,
                        id: si.external_id,
                        title: si.title,
                        desc: si.description,
                        category: si.category as any,
                        severity: si.severity as Severity,
                        fix: si.fix_plan || '',
                        isDone: si.is_done,
                        assigneeEmail: si.assignee_email || '',
                        collaboratorNote: si.collaborator_note || '',
                    })));
                }
                fetchRecentAudits();
            })
            .subscribe();

        return () => {
            supabase.removeChannel(channel);
        };
    }, [supabase, currentAuditId]);

    useEffect(() => {
        ensureCurrentUserProfile();
    }, [session?.user.id, currentUserEmail]);

    const fetchUserConfig = async () => {
        if (!supabase || !session) return;
        const { data, error } = await supabase
