// Instrucciones para Gemini / Groq
// IMPORTANTE: Groq requiere que el prompt contenga la palabra "json"
// cuando se usa response_format: { type: "json_object" }.
const SYSTEM_INSTRUCTION = `Eres el sistema central de auditoría SYNAPSE // QA.
Tu misión es procesar reportes técnicos con precisión quirúrgica.
1. Analiza con rigor: fallos de UI, errores de lógica, problemas de codificación (UTF-8) y regresiones funcionales.
2. Clasifica obligatoriamente en: 'UI/UX', 'Backend', 'Datos', 'Seguridad', 'Rendimiento'.
3. El resumen ejecutivo debe ser directo, técnico y profesional (evita saludos).
4. Para cada hallazgo:
   - Título: Conciso y técnico.
   - Descripción: Detalle del comportamiento observado vs esperado.
   - Severidad: Alta/Media/Baja.
   - Solución: Instrucciones técnicas de remediación.
RESPONDE SIEMPRE EN ESPAÑOL. Usa terminología de ingeniería de software moderna.
DEVUELVE ÚNICAMENTE un objeto JSON válido con la estructura:
{ "summary": string, "issues": Array<{ id, title, desc, category, severity, fix }> }`;

const TASK_SYSTEM_INSTRUCTION = `Eres el gestor de incidentes SYNAPSE // TASKS.
Tu misión es transformar descripciones de lenguaje natural en una lista estructurada de tareas técnicas pendientes (To-Do List).
1. Analiza el texto entrada buscando intenciones, pendientes y requerimientos.
2. Identifica verbos de acción y contextos técnicos.
3. Añade al menos un "summary" o "resumen" general de las tareas que explique su propósito.
4. Clasifica cada tarea obligatoriamente en: 'UI/UX', 'Backend', 'Datos', 'Seguridad', 'Rendimiento'.
5. Asigna prioridad (Severity) basada en la urgencia o importancia del contexto (ej: seguridad/crítico -> Alta).
6. Para cada tarea incluye campos claramente nombrados: 'title' (resumen breve), 'desc' (detalle del trabajo), una breve 'fix' o 'plan_tecnico' con la sugerencia de resolución técnica y, si aplica, 'category' y 'severity'.
7. Estructura de salida JSON e incluye el campo "issues" con el arreglo de tareas y "summary" con el texto principal.
RESPONDE SIEMPRE EN ESPAÑOL.
DEVUELVE ÚNICAMENTE un objeto JSON válido con la estructura:
{ "summary": string, "issues": Array<{ id, title, desc, category, severity, fix }> }`;

// Endpoint de análisis de issues
app.post('/api/analyze', aiLimiter, async (req, res) => {
  const { input, provider, apiKey, isTask } = req.body;

  // Validación: el input no puede estar vacío ni exceder 10,000 caracteres
  if (!input || typeof input !== 'string' || !input.trim()) {
    return res.status(400).json({ error: 'El campo "input" es requerido.' });
  }
  if (input.length > 10000) {
    return res.status(400).json({ error: `El texto de entrada supera el límite de 10,000 caracteres (actual: ${input.length}).` });
  }
  // Usar la key del body (del usuario) o la del servidor (.env)
  const geminiKey = apiKey || process.env.GEMINI_API_KEY || process.env.VITE_GEMINI_API_KEY;
  const groqKey = apiKey || process.env.GROQ_API_KEY || process.env.VITE_GROQ_API_KEY;

  try {
    if (provider === 'gemini') {
      if (!geminiKey) return res.status(400).json({ error: 'Falta Gemini API Key' });

      const genAI = new GoogleGenAI({ apiKey: geminiKey });
      const model = genAI.getGenerativeModel({
        model: "gemini-2.0-flash",
        systemInstruction: isTask ? TASK_SYSTEM_INSTRUCTION : SYSTEM_INSTRUCTION
      });

      const result = await model.generateContent(input);
      const response = await result.response;
      let text = response.text();

      // Limpiar markdown si Gemini lo envía
      text = text.replace(/```json/g, '').replace(/```/g, '').trim();

      // parsear y normalizar para asegurar campos mínimos
      const parsed = JSON.parse(text);
      if (parsed) {
        parsed.summary = parsed.summary || parsed.resumen || '[sin resumen]';
        if (Array.isArray(parsed.issues)) {
          parsed.issues = parsed.issues.map((i, idx) => {
            const id = i.id || i.ID || i.external_id || idx + 1;
            const title = i.title || i.titulo || i.descripcion || i.description || '[sin título]';
            const desc = i.desc || i.descripcion || i.detalles || i.detail || '[sin descripción]';
            const fix = i.fix || i.resolucion || i.plan_tecnico || i.plan_accion || i.plan || '';
            const rawSeverity = i.severity || i.prioridad || i.gravedad || i.level || 'Baja';
            return {
              ...i,
              id,
              title,
              desc,
              fix,
              severity: rawSeverity
            };
          });
        }
      }

      res.json(parsed);

    } else if (provider === 'groq') {
      if (!groqKey) return res.status(400).json({ error: 'Falta Groq API Key' });

      // para mantener consistencia, reutilizamos las mismas instrucciones que
      // usamos con Gemini; de este modo ambos proveedores reciben el mismo
      // contexto detallado y es más fácil ajustar el prompt en un único lugar.
      const systemPrompt = isTask ? TASK_SYSTEM_INSTRUCTION : SYSTEM_INSTRUCTION;

      const response = await fetch("https://api.groq.com/openai/v1/chat/completions", {
        method: "POST",
        headers: {
          "Authorization": `Bearer ${groqKey}`,
          "Content-Type": "application/json"
        },
        body: JSON.stringify({
          model: "llama-3.3-70b-versatile",
          messages: [
            { role: "system", content: systemPrompt },
            { role: "user", content: input }
          ],
          // el tipo 'json_object' ya nos obliga a recibir JSON válido, pero
          // también podríamos añadir un esquema si se necesitara validar
          // campos concretos. Por ahora las instrucciones del systemPrompt
          // piden explícitamente title/desc/severity/fix/category.
          response_format: { type: "json_object" },
          temperature: 0.1
        })
      });

      const data = await response.json();
      if (data.error) throw new Error(data.error.message);

      res.json(JSON.parse(data.choices[0].message.content));
    } else {
      res.status(400).json({ error: 'Proveedor no válido' });
    }
  } catch (error) {
    console.error('Error en Proxy IA:', error);
    res.status(500).json({ error: error.message });
  }
});

// --- FIN PROXY IA ---

