/* Reset de Scrollbar (Global) */
* {
  scrollbar-width: none;
  -ms-overflow-style: none;
}

*::-webkit-scrollbar {
  display: none;
}

html {
  scroll-behavior: smooth;
  overflow-x: hidden;
  min-height: 100%;
